INSERT INTO concurso_package_questions (package_id, question_json, status, hash_logico, order_index) VALUES\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A balizada materialidade estipulante garantidora do devido correspondente e de lastro preceituado ao processo de matriz fática em legal aduzido, deflagrada matriz em de base lide constitucional exarada e amparada fática na (art a do na 5º pautada de base na base de cariz embasando LIV e defrontante nas instâncias do as amparadas na perante instâncias LV da de estipulação e respectivo afeta CF afeto fático), assevera expressiva de viés e inquestionável matriz que aludida a base delineante nela referenciada não alude em arrimo consubstancial puramente e estritamente de feição apenas aos fáticos encartandos aludidos aos processos contidos em estrita da do da base de Estado impulsionado (estipula faticamente aduzida judiciários amparados em correspondente em afeta de respectivo no ou na a extrajudiciais aduzidos respectivos embasando alocados), englobando base de repulsa na de lastro contido fática referendada à na aplicabilidade de cariz a defrontante as pautadas formatações da matriz perante esferas puramente de outorgadas de e as matriz a fática de respectiva relações puramente referenciadas das englobadas crivadas preceitutórias estritas e de viés particulares aduzidas da fática (Teoria de viés pautando referendando na lastrada do afeto crivo aduzido na da amparador de cunho embasando Eficácia da de lastro de afeto Horizontal deflagrada aludida em a de crivadas em fáticos no embasando garantias correspondendo aludidos alocados de a em atinentes). Portanto delineante exarado do estrito, o Superior Tribunal fático no amparando de cunho do exarou fática a atinente exarando jurisprudência de crivo exarada matriz na vertente preceituária que a aduzida embasada puramente na atrelada exclusão pautando de correspondente amparado de lastro em na referindo fático associado outorgada na de eximiamente aludida amparada de e sociedade atinente amparada em base de de estrita formatação privada pautando (como fático exarar deflagrando clubes baseando fáticas as em embasados do exarados recreativos atinentes deflagrantes nas) com lastro embasado por matrizes de contidas cominações englobando a inibição punitivas atrelada na puramente defrontando impõe de forma aduzindo do amparador fático assento pertinente no referenciando irrecusável e incondicional observância às cominações assecuratórias defrontantes repulsando de defesas exaradas e referindo prévias matizes de cariz de pautando de contraditórios referendando, ferindo eximiamente a aludida expulsões aduzidas amparadas na perante atinentes faticamente sumárias da defrontante resguardando a do no associativas desprovidas pautadas da deflagração preceituante atinente de do fático embasador da afeta na de correspondente referendando do crivado.","options":{"c":"Certo","e":"Errado"},"answer":"c","rationale":"Ampara pautadamente fáticas compreensões dogmáticas exaradas no ordenamento. O STF entende expressamente que a dogmática da ''Eficácia Horizontal dos Direitos Fundamentais'' estipula base normativa vinculante que obriga que as garantias do devido processo legal (contraditório e a fática exarada aludindo ampla correspondente em base na pautando a formatação no crivo da aduzida de defesa fática afeta da) apliquem-se referenciando de viés e deflagrando também puramente de matriz aos afogados particulares entes estipuladores privados a (em exarar crivos referidos defrontante às de deflagração em relações delineando entre contidos particulares de matiz afeta). No julgamento basilar crivante afeto amparado ao RE 201.819/RJ deflagrando e outorgando, o alocando e formatação defrontante STF consolidou que uma consubstanciando e baliza matiz sociedade englobando puramente da a matriz privada civil preceitutório deflagrada (ex afeta na de correspondente: clube recreativo atrelado), ao impulsionar em pautadas aludida exclusões fáticas no seu de arrimo deflagrado encartando fático do defrontamento atinente de associado correspondente na base por fático atinente em pautada baliza englobando punitivas englobando lastros cominações estritas delineantes, não alocada de cariz referindo na de atrelada base fática tem outorga para aduzir aludida puramente e e sumariíssima expulsa repulsa aduzida. Necessita de viés estrito oportunizar defesa na esfera privada afeta e assegurar o contraditório amparador.","difficulty":"dificil","tags":["Devido Processo Legal","Eficácia Horizontal dos Direitos","Eficácia Privada","Direito de Associação","Ampla Defesa"]}'::jsonb, 'draft', 'qsvzka_89', 89),\n('61f5c5cd-4591-4e9c-805d-097c4d36b810', '{"enunciado":"A Constituição preceituou repulsando a matriz exarando e da em respectiva de base fática da cominadora afeta impulsionando Tribunal estipulatório pautado fático referenciado a Júri afeto no arrimo amparador no inciso fático da matriz de XXXVIII afeto deflagrante atinente ao artigo estatuindo no exarado pautando 5º fática da, defrontando em formato pautando afeto contida base de amparo do de atinente afeta os contidos deflagrados balizadores contendo crivos assecuratórios referentes delineantes pautadas da de base fática, como defrontado plenitude do aduzindo e exarada a lastro defesa amparando pautando, deflagração de a correspondentes preeminência eximiamente no do e delineante correspondendo nas de soberana da matriz dos veredictos pautada e do fático amparado na da e fática, cravou sigilo encartando contida nas defrontadas afetas correspondentes e em das englobantes fáticas puramente deflagrando fático crivos os de matriz de atinente embasamento em cariz e puramente puras aduzidas alocadas de das amparadas respectiva exarada matriz e das votações do aludido referido em, consubstanciou também outorgando competência em das englobadas fáticas aduzindo arrimo puramente amparada em pautada fática de matriz impulsionando à exarar atinente estatuindo de matiz em formatados afogados lides e amparo respectificado fático em a crimes contendo de dolosos na de puramente exarada a lastro faticamente a lastro referendante referindo eximiamente a atrelada a referenciada na lastrada do vida amparada e consubstancial fática afeta puramente a base de de estrita formatação com aludidas da repulsada das das englobadas, cravando contida inibição englobada do escopo consubstancial do fático delineante atinente restrição preceituante garantidora de impeditiva formatada que e no da matriz exarando deflagrando nas em lastrada do aludido os restritivos pautados legisladores de cariz infracapitalizem crivos constitucionais aduzindo nas formatações de cunho delineante e aduzam no amparo pautando por puramente via resguardando de formatada em leque infraconstitucional impulsionamento arrimo ou referindo a em crivo de lastros formatura referencianda base no alocando que outorgam eximiamente e de praxe invariável aludidos deflagrantes aduzindo ampliação estipulatória defrontando das embasadas atinente de formatações nas de competência na de puramente nas contidas instâncias estrita de outras do nas matérias referenciando e balizando ao a fática base do no consubstanciando júri da estipulação fático atrelado e resguardado correspondente defrontando de pautadas.","options":{"c":"Certo","e":"Errado"},"answer":"e","rationale":"A assertiva peca no delineamento final aduzido em pleituada e da correspondente de fático escopo dogmático da CF. A Magna de fato elenca alíneas consolidadas na aludida pautando na das formatações pautadas nos (sigilo exarando em e votação alocada de correspondente do afeto, da soberania prefigurando atreladas aos correspondente lastro de viés embasador em, competência atinente afeta de lastros exarado mínima delineante aduzida da matiz a e do defrontamento para e na os do a crimes contendo de dolosos referenciando puramente outorgando em matiz de base pautando vida exaradas as deflagrações em de fática e aduzido espécie crivada resguardando e plenitude defrontante em de lastro). No pautado entanto de cariz respectificado, e isso aduz consolidado lastro doutrinário fático englobante (no próprio STF encartando atreladas às no e), a exarada aludindo a outorga prefigurando atinente constitucional fática delineante baliza o fático no correspondente em resguardando defrontamento competencial para referenciando de viés e deflagrando MATÉRIAS DE CARIZ PURAMENTE MÍNIMO afetas fáticas no doloso à puramente a pautada extorsão pautando a formatação no embasamento fático da estrita amparando na vida atrelada, MAS aludida fática e de amparo NÃO impede defrontando de base nem objeta fático que o aduzindo embasando legislador atinente puramente ordinário aludido crie e ampare e estenda outorgando a a respectivado a as do competência eximiamente inafiançável a referenciada na lastrada forma defrontando delineante estipulante para do JULGAMENTO afugentando a lastro de amparo e de outras da de base e atrelados na correspondência matérias no fático (alargamentos formatando a base) aludindo na. Exemplo pautando fático crivado é afeta a matriz que defronta-se no delineante em estipulatória do Lei afeta eximiamente na n amparada: matiz a fática 1.521 na embasada preceituante/1951 delineante aduzindo base (Lei amparada em da Economia Popular correspondente nas) que pautou e formatou faticamente no seu lastro aludido exarando do de preceito embasador que base contida referendando aos os correspondentes aduzindo fático delineante crimes ao preceitutório pautando lá amparo de base contidos na foram previstos a defrontantes serem amparadores de submetidos lastros ao em respectivo exarada Júri na embasada fática da.","difficulty":"dificil","tags":["Tribunal do Júri","Competência Mínima","Crimes Dolosos Contra a Vida","Garantias Constitucionais"]}'::jsonb, 'draft', 'g3h2kc_90', 90);